/bin/zsh -lc "python3 -B - <<'PY'
from app.errors import ConfigError
from app.port import parse_port

valid = {'1': 1, '65535': 65535, '00080': 80}
invalid = ['bad', '', '0', '65536', None, 80, True, '1.0', ' 80', '-1', '²', '9' * 5000]
for value, expected in valid.items():
    assert parse_port(value) == expected, value
for value in invalid:
    try:
        parse_port(value)
    except ConfigError:
        pass
    else:
        raise AssertionError(f'expected ConfigError for {value"'!r}'"')
print(f'passed: {len(valid)} valid and {len(invalid)} invalid inputs')
PY"

